ALTER TABLE "User" ADD COLUMN "gmailScopes" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "gmailSendOnlyConsentAt" TIMESTAMP(3);
ALTER TABLE "Send" ADD COLUMN "replyMarkedAt" TIMESTAMP(3), ADD COLUMN "bouncedAt" TIMESTAMP(3), ADD COLUMN "sentConfirmedManuallyAt" TIMESTAMP(3);
CREATE TYPE "SuppressionReason" AS ENUM ('DO_NOT_CONTACT', 'MANUAL_BOUNCE');
CREATE TABLE "RecipientSuppression" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  "email" TEXT NOT NULL,
  "reason" "SuppressionReason" NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX "RecipientSuppression_userId_email_key" ON "RecipientSuppression"("userId", "email");
